from __future__ import annotations

from pathlib import Path
from typing import Iterable

from docx import Document
from docx.enum.table import WD_ALIGN_VERTICAL, WD_TABLE_ALIGNMENT
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Cm, Pt

BASE_DIR = Path(__file__).resolve().parent
OUT_DOCX = BASE_DIR / 'chapter1_problem_analysis.docx'
OUT_TEXT = BASE_DIR / 'chapter1_problem_analysis_source.txt'

BODY_FONT = 'Times New Roman'
BODY_SIZE = Pt(14)
TABLE_SIZE = Pt(12)
FIRST_LINE = Cm(1.25)
LINE_SPACING = 1.5


def paragraph_block(text: str) -> list[str]:
    return [chunk.strip() for chunk in text.strip().split('\n\n') if chunk.strip()]


def set_run_font(run, *, bold=None, italic=None, size=BODY_SIZE, name=BODY_FONT):
    run.font.name = name
    run._element.rPr.rFonts.set(qn('w:ascii'), name)
    run._element.rPr.rFonts.set(qn('w:hAnsi'), name)
    run._element.rPr.rFonts.set(qn('w:cs'), name)
    run.font.size = size
    if bold is not None:
        run.bold = bold
    if italic is not None:
        run.italic = italic


def format_body_paragraph(p):
    p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.first_line_indent = FIRST_LINE
    p.paragraph_format.line_spacing = LINE_SPACING
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(0)
    for run in p.runs:
        set_run_font(run)


def format_heading_paragraph(p, *, center=False, before=6, after=6):
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER if center else WD_ALIGN_PARAGRAPH.LEFT
    p.paragraph_format.first_line_indent = None
    p.paragraph_format.line_spacing = LINE_SPACING
    p.paragraph_format.space_before = Pt(before)
    p.paragraph_format.space_after = Pt(after)
    for run in p.runs:
        set_run_font(run, bold=True)


def format_caption_paragraph(p):
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.first_line_indent = None
    p.paragraph_format.line_spacing = LINE_SPACING
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(0)
    for run in p.runs:
        set_run_font(run)


def add_heading(doc: Document, text: str, *, level: int = 1):
    p = doc.add_paragraph()
    run = p.add_run(text)
    set_run_font(run, bold=True)
    format_heading_paragraph(p, center=(level == 1), before=12 if level == 1 else 6, after=6)
    return p


def add_body(doc: Document, text: str):
    p = doc.add_paragraph(text)
    format_body_paragraph(p)
    return p


def add_caption(doc: Document, text: str):
    p = doc.add_paragraph(text)
    format_caption_paragraph(p)
    return p


def shade_cell(cell, fill: str):
    tc_pr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement('w:shd')
    shd.set(qn('w:fill'), fill)
    tc_pr.append(shd)


def set_cell_text(cell, text: str, *, bold=False, align='left', size=TABLE_SIZE):
    cell.text = ''
    p = cell.paragraphs[0]
    p.alignment = {
        'left': WD_ALIGN_PARAGRAPH.LEFT,
        'center': WD_ALIGN_PARAGRAPH.CENTER,
        'right': WD_ALIGN_PARAGRAPH.RIGHT,
        'justify': WD_ALIGN_PARAGRAPH.JUSTIFY,
    }[align]
    p.paragraph_format.first_line_indent = None
    p.paragraph_format.line_spacing = 1.0
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(0)
    run = p.add_run(str(text))
    set_run_font(run, bold=bold, size=size)
    cell.vertical_alignment = WD_ALIGN_VERTICAL.CENTER


def add_table(doc: Document, caption: str, headers: list[str], rows: list[list[str]], *, col_widths_cm: list[float] | None = None):
    add_caption(doc, caption)
    table = doc.add_table(rows=1, cols=len(headers))
    table.style = 'Table Grid'
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    hdr = table.rows[0].cells
    for idx, text in enumerate(headers):
        set_cell_text(hdr[idx], text, bold=True, align='center')
        shade_cell(hdr[idx], 'D9EAF7')
        if col_widths_cm and idx < len(col_widths_cm):
            hdr[idx].width = Cm(col_widths_cm[idx])
    for row in rows:
        cells = table.add_row().cells
        for idx, text in enumerate(row):
            align = 'center' if idx == 0 else 'left'
            set_cell_text(cells[idx], text, align=align)
            if col_widths_cm and idx < len(col_widths_cm):
                cells[idx].width = Cm(col_widths_cm[idx])
    doc.add_paragraph('')
    return table


def ensure_default_style(doc: Document):
    style = doc.styles['Normal']
    style.font.name = BODY_FONT
    style.font.size = BODY_SIZE
    style._element.rPr.rFonts.set(qn('w:ascii'), BODY_FONT)
    style._element.rPr.rFonts.set(qn('w:hAnsi'), BODY_FONT)
    style._element.rPr.rFonts.set(qn('w:cs'), BODY_FONT)
    style.paragraph_format.first_line_indent = FIRST_LINE
    style.paragraph_format.line_spacing = LINE_SPACING
    for section in doc.sections:
        section.top_margin = Cm(2)
        section.bottom_margin = Cm(2)
        section.left_margin = Cm(3)
        section.right_margin = Cm(1.5)


def add_section_paragraphs(doc: Document, paragraphs: Iterable[str]):
    for text in paragraphs:
        add_body(doc, text)


CHAPTER_TITLE = '1 Проблемный анализ предметной области диагностики серверного оборудования'

INTRO = paragraph_block('''
Диагностика серверного оборудования в современных информационных системах является не только инженерной задачей контроля исправности узлов, но и задачей принятия решений в условиях риска и неопределённости. Сервер обеспечивает выполнение прикладных сервисов, хранение данных, сетевое взаимодействие, обработку запросов пользователей и работу фоновых процессов. Его отказ или деградация приводят к простою, нарушению доступности сервисов, потере производительности, росту трудозатрат на восстановление и, в отдельных случаях, к потере данных.

Традиционная практика мониторинга строится вокруг текущих значений метрик и пороговых правил: если температура, загрузка CPU, использование памяти или число аппаратных предупреждений превысили допустимое значение, оператор получает сигнал. Такой подход необходим, но недостаточен для диссертационной постановки. Пороговое правило фиксирует факт опасного режима или близость к нему, но не отвечает на более важные вопросы: что произойдёт на горизонте 24 часа, 7 суток или 30 суток; насколько достоверен прогноз; какие метрики внесли наибольший вклад в риск; какое действие уменьшит ожидаемые потери.

Для решения указанной задачи требуется перейти от реактивного мониторинга к прогнозной диагностике. В такой постановке серверная телеметрия рассматривается как поток временных рядов, на основе которого строятся прогнозные траектории, вероятности состояний, риск отказа и рекомендации для лица, принимающего решение. Научная сложность состоит в том, что данные неполны, шумны, имеют сезонность, зависят от режима эксплуатации, а реальные отказы встречаются существенно реже нормальных наблюдений. Поэтому задачу нельзя корректно свести к простой детекции аномалий по правилу «всё, что вне нормы, является аномалией».

В данной главе выполняется проблемный анализ предметной области диагностики серверного оборудования. Рассматриваются рисковые ситуации и последствия отказов серверных систем, специфика функционирования серверного оборудования, особенности сбора и агрегации эксплуатационных метрик, паттерны деградации аппаратных компонентов и программных сервисов, а также ограничения существующих систем мониторинга и поддержки принятия решений.
''')

SEC11 = paragraph_block('''
Риск в задачах эксплуатации серверных систем целесообразно рассматривать как сочетание вероятности неблагоприятного события и тяжести его последствий. Такой подход согласуется с общими принципами управления рисками, закреплёнными в ISO 31000, где риск трактуется как влияние неопределённости на достижение целей [4]. Для серверной инфраструктуры такими целями являются доступность сервисов, сохранность данных, устойчивость производительности, соблюдение регламентов обслуживания и минимизация эксплуатационных затрат.

Рисковая ситуация возникает не только при полном отказе оборудования. На практике существенную опасность представляют промежуточные состояния: рост температуры, деградация дисковой подсистемы, исчерпание памяти, постоянная высокая загрузка CPU, рост сетевой задержки, сбои резервного копирования, деградация RAID-массива, потеря связи с агентом мониторинга. Такие ситуации не всегда немедленно приводят к аварии, но увеличивают вероятность неблагоприятного сценария и требуют управленческой реакции.

Последствия отказов серверных систем имеют несколько уровней. Технический уровень связан с недоступностью узла, потерей производительности, ошибками ввода-вывода и нарушением целостности данных. Организационный уровень связан с необходимостью внепланового обслуживания, привлечения администратора, переноса нагрузки или восстановления из резервной копии. Экономический уровень выражается в простое сервисов, штрафах за нарушение SLA, потере пользовательской лояльности и затратах на замену компонентов. Поэтому оценка риска должна учитывать не только вероятность отказа, но и стоимость последствий.

Эмпирические исследования отказов оборудования подтверждают, что реальные отказы серверных компонентов имеют сложную природу. В крупном исследовании Google по отказам дисковых накопителей показано, что SMART-показатели могут быть связаны с вероятностью отказа, но не обеспечивают полной предсказуемости: часть отказов происходит без явных предварительных признаков, а часть предупреждений не приводит к немедленному отказу [15]. Исследования Schroeder и Gibson также показывают, что фактическая надёжность дисков в эксплуатации может отличаться от паспортных оценок MTTF [16]. Для оперативной памяти выявлены ошибки, которые в реальных системах распределяются неравномерно и зависят от условий эксплуатации [17].

Из этого следует важный вывод: диагностика серверного оборудования не должна строиться как бинарная схема «здоров — неисправен». Более корректной является шкала состояний и риска. В диссертационной системе такая шкала может быть представлена состояниями S0, S1 и S2, где S0 соответствует нормальному режиму, S1 — признакам деградации, а S2 — предаварийному состоянию. Это не означает, что физически сервер имеет только три состояния. Данная шкала является управленческой моделью, позволяющей связать техническую телеметрию с решением оператора.

При оценке риска важно учитывать ожидаемую стоимость ошибок. Ложная тревога приводит к лишним трудозатратам, ненужному переключению нагрузки или преждевременной замене компонента. Пропуск отказа может привести к простою и более тяжёлым последствиям. Классическая статистическая теория решений, представленная в работах A. Wald и L. Savage, рассматривает выбор действия как задачу минимизации функции потерь при неопределённости [5; 6]. В прикладной эксплуатации серверов это означает, что решение следует принимать не по одному факту превышения порога, а по ожидаемым потерям альтернативных действий.

Под риском отказа в данной работе понимается интегральная оценка неблагоприятного сценария на заданном горизонте времени. Такая оценка должна учитывать прогнозные значения метрик, неопределённость прогноза, физическую природу метрики, историю состояний устройства и стоимость последствий. Поэтому риск в системе является не самостоятельным «датчиком», а вычисляемым показателем, получаемым из цепочки «телеметрия — прогноз — состояние — последствия».
''')

