def write_source_text() -> None:
    parts: list[str] = [CHAPTER_TITLE, *INTRO, '']
    for title, paragraphs, table in SECTIONS:
        parts.append(title)
        parts.extend(paragraphs)
        if table:
            parts.append(table['caption'])
            parts.append(' | '.join(table['headers']))
            parts.extend(' | '.join(row) for row in table['rows'])
        parts.append('')
    parts.append('Выводы по главе 1')
    parts.extend(CONCLUSION)
    parts.append('')
    parts.append('Список использованных источников')
    parts.extend(f'[{idx}] {item}' for idx, item in enumerate(BIBLIOGRAPHY, start=1))
    OUT_TEXT.write_text('\n\n'.join(parts), encoding='utf-8')


def build_docx() -> None:
    doc = Document()
    ensure_default_style(doc)

    add_heading(doc, CHAPTER_TITLE, level=1)
    add_section_paragraphs(doc, INTRO)

    for title, paragraphs, table in SECTIONS:
        add_heading(doc, title, level=2)
        add_section_paragraphs(doc, paragraphs)
        if table:
            add_table(doc, table['caption'], table['headers'], table['rows'], col_widths_cm=table['col_widths'])

    add_heading(doc, 'Выводы по главе 1', level=2)
    add_section_paragraphs(doc, CONCLUSION)

    add_heading(doc, 'Список использованных источников', level=1)
    for idx, item in enumerate(BIBLIOGRAPHY, start=1):
        p = doc.add_paragraph(f'[{idx}] {item}')
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        p.paragraph_format.first_line_indent = None
        p.paragraph_format.line_spacing = LINE_SPACING
        p.paragraph_format.space_before = Pt(0)
        p.paragraph_format.space_after = Pt(0)
        for run in p.runs:
            set_run_font(run)

    doc.save(str(OUT_DOCX))

    word_count = sum(len([w for w in p.text.split() if w.strip()]) for p in doc.paragraphs)
    print(f'Created: {OUT_DOCX}')
    print(f'Created: {OUT_TEXT}')
    print(f'Word count: {word_count}')
    print(f'Paragraphs: {len(doc.paragraphs)}')
    print(f'Sources: {len(BIBLIOGRAPHY)}')


if __name__ == '__main__':
    write_source_text()
    build_docx()
